import heapq
from collections import Counter


def ledger(data, priority, tax_base, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if priority == "revision_first":
            key = (event.get("revision", 0), pos)
        else:
            key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if tax_base == "discounted" else raw
        tax = rounded(base * event.get("tax_bp", 0))
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        stack = []
        valid = True
        for name, bounds in data["roots"].items():
            row = installed.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
            stack.append(name)
        if not valid:
            continue

        reached = set()
        edges = {}
        while stack and valid:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            row = installed[name]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                target = installed.get(other)
                if (target is None or
                        not dep["min"] <= target["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                if other not in reached:
                    stack.append(other)
        if not valid or reached != set(installed):
            continue

        active, finished = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in edges):
            continue

        vector = tuple(installed[name]["version"] if name in installed else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: installed[name]["version"]
                             for name in names if name in installed}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def quota_solver(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        timeline = []
        for job in subset:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(timeline):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        ordered_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids < best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def route_solver(data):
    required = data.get("required", [])
    bit_for = {}
    for i, node in enumerate(required):
        bit_for[node] = bit_for.get(node, 0) | (1 << i)
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(remaining, edge["duration"])]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((remaining - 1, duration))
            for next_remaining, duration in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask,
                                           next_remaining))

    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: ledger(data, "revision_first", "discounted", False),
    "component_02": lambda data: ledger(data, "sequence_first", "discounted", True),
    "component_03": lambda data: ledger(data, "revision_first", "original", False),
    "component_04": lambda data: ledger(data, "sequence_first", "original", True),
    "component_05": lambda data: ledger(data, "revision_first", "discounted", True),
    "component_06": dependency_solver,
    "component_07": quota_solver,
    "component_08": route_solver,
}
